import{_ as t,o as a,c as i,ao as n}from"./chunks/framework.DdhParCf.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"JosephsonCircuits.jl","text":"Simulate superconducting circuits","tagline":"Harmonic balance and transient simulation of Josephson circuits. Calculate gain, frequency conversion, stability, noise, and sensitivities.","image":{"light":"/logo.svg","dark":"/logo-dark.svg","alt":"JosephsonCircuits.jl"},"actions":[{"theme":"brand","text":"Get started","link":"/quickstart"},{"theme":"alt","text":"Examples","link":"/examples"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/kpobrien/JosephsonCircuits.jl"}]},"features":[{"title":"Build a circuit","details":"Connect junctions, linear components, subcircuits, scattering models, and transmission lines.","link":"/circuits"},{"title":"Harmonic balance","details":"Find a driven operating point and calculate its small-signal response, noise, and sensitivities.","link":"/harmonicbalance"},{"title":"Transient simulation","details":"Simulate pulses and multiple strong tones. Measure the response and quantum noise in time windows.","link":"/transient"},{"title":"API reference","details":"Constructors, solvers, result types, and advanced interfaces.","link":"/reference"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),r={name:"index.md"};function s(o,e,l,c,h,d){return a(),i("div",null,[...e[0]||(e[0]=[n(`<p>JosephsonCircuits.jl simulates nonlinear microwave circuits containing Josephson junctions. It is designed for devices such as Josephson parametric amplifiers and traveling-wave amplifiers with thousands of components.</p><p>Use <strong>harmonic balance</strong> for a steady driven state and its small-signal response. Use <strong>transient simulation</strong> for pump turn-on, pulses, and drives with too many independent tones for a practical harmonic grid. Both analyses use the same circuit description, subject to the <a href="/dev/circuits#Supported-analyses">component restrictions</a>.</p><p>The noise calculations propagate small fluctuations about a classical operating point or trajectory. They describe Gaussian quantum noise; they do not evolve the full quantum state of a nonlinear circuit.</p><h2 id="Installation" tabindex="-1">Installation <a class="header-anchor" href="#Installation" aria-label="Permalink to &quot;Installation {#Installation}&quot;">​</a></h2><p>In a Julia environment, install the registered release with:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;JosephsonCircuits&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Then follow the <a href="./quickstart">first calculation</a>. The plotting examples also need <code>Plots</code>; examples using external solvers or WRspice list their additional dependencies.</p><p>The version selector distinguishes the released manual from development versions. Development documentation can describe APIs that are not yet in the registered release. To use the current development branch:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;JosephsonCircuits&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rev </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>If an example does not match your installation, check <code>Pkg.status()</code> and <code>VERSION</code> first. Include those values and a minimal reproducer in a bug report. See the <a href="./migration">migration guide</a> for the changes since v0.5.4.</p><h2 id="A-first-calculation" tabindex="-1">A first calculation <a class="header-anchor" href="#A-first-calculation" aria-label="Permalink to &quot;A first calculation {#A-first-calculation}&quot;">​</a></h2><p>The <a href="./quickstart">quickstart</a> builds a one-port JPA, solves its pumped operating point, and reads its reflection gain. It also shows how to apply the same pump in time, including the Fourier-amplitude convention.</p><h2 id="How-the-documentation-is-organized" tabindex="-1">How the documentation is organized <a class="header-anchor" href="#How-the-documentation-is-organized" aria-label="Permalink to &quot;How the documentation is organized {#How-the-documentation-is-organized}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Task</th><th style="text-align:right;">Start here</th></tr></thead><tbody><tr><td style="text-align:right;">Run a first simulation</td><td style="text-align:right;"><a href="./quickstart">Quickstart</a></td></tr><tr><td style="text-align:right;">Check units or normalization</td><td style="text-align:right;"><a href="./conventions">Conventions</a></td></tr><tr><td style="text-align:right;">Define components and connections</td><td style="text-align:right;"><a href="./circuits">Circuits</a></td></tr><tr><td style="text-align:right;">Include measured data or a fitted amplifier</td><td style="text-align:right;"><a href="./scattering">Scattering blocks</a></td></tr><tr><td style="text-align:right;">Find a driven operating point and gain</td><td style="text-align:right;"><a href="./harmonicbalance">Harmonic balance</a></td></tr><tr><td style="text-align:right;">Test temporal stability of a driven state</td><td style="text-align:right;"><a href="./stability">Harmonic-balance stability</a></td></tr><tr><td style="text-align:right;">Warm ports, a readout chain&#39;s efficiency, the noise reaching a qubit</td><td style="text-align:right;"><a href="./portnoise">Noise at the ports</a></td></tr><tr><td style="text-align:right;">Simulate pulses</td><td style="text-align:right;"><a href="./transient">Transient simulation</a></td></tr><tr><td style="text-align:right;">Calculate fluctuations in temporal modes</td><td style="text-align:right;"><a href="./transientnoise">Quantum noise in time</a></td></tr><tr><td style="text-align:right;">Reuse work or run on a GPU</td><td style="text-align:right;"><a href="./performance">Performance</a></td></tr><tr><td style="text-align:right;">Supply another numerical solver</td><td style="text-align:right;"><a href="./interop">Using other solvers</a></td></tr><tr><td style="text-align:right;">Understand the equations and algorithms</td><td style="text-align:right;"><a href="./harmonicbalancetheory">HB theory</a>, <a href="./transienttheory">transient theory</a></td></tr></tbody></table><h2 id="Supported-calculations" tabindex="-1">Supported calculations <a class="header-anchor" href="#Supported-calculations" aria-label="Permalink to &quot;Supported calculations {#Supported-calculations}&quot;">​</a></h2><ul><li><p>Nonlinear steady states with one or more strong drive tones.</p></li><li><p>Small-signal scattering, frequency conversion, quantum efficiency, and sensitivities about a driven state.</p></li><li><p>Temporal stability poles about a driven state, with method-specific limits and convergence checks in the <a href="./stability">stability guide</a>.</p></li><li><p>Linear circuit responses, and the circuit matrices with the component values left as expressions in their parameters (<a href="/dev/api/circuits#JosephsonCircuits.symbolicmatrices-Tuple{Union{JosephsonCircuits.CompiledCircuit, JosephsonCircuits.ElaboratedCircuit, Circuit}}"><code>symbolicmatrices</code></a>).</p></li><li><p>Transient trajectories, their tangent and adjoint responses, and noise in selected temporal modes.</p></li></ul><p>The <a href="./examples">examples</a> include comparisons with WRspice. Reference 6 below describes comparisons of the frequency-domain solver with ADS and Fourier analysis of WRspice simulations.</p><h2 id="Contributing" tabindex="-1">Contributing <a class="header-anchor" href="#Contributing" aria-label="Permalink to &quot;Contributing {#Contributing}&quot;">​</a></h2><p>We welcome contributions in the form of issues/bug reports or pull requests. This project uses the <a href="https://opensource.org/license/MIT" target="_blank" rel="noreferrer">MIT open source license</a>. You retain the copyright to any code you contribute.</p><h2 id="References" tabindex="-1">References <a class="header-anchor" href="#References" aria-label="Permalink to &quot;References {#References}&quot;">​</a></h2><ol><li><p>Andrew J. Kerman &quot;Efficient numerical simulation of complex Josephson quantum circuits&quot; <a href="https://doi.org/10.48550/arXiv.2010.14929" target="_blank" rel="noreferrer">arXiv:2010.14929 (2020)</a></p></li><li><p>Jiří Vlach and Kishore Singhal &quot;Computer Methods for Circuit Analysis and Design&quot; 2nd edition, <a href="https://link.springer.com/book/9780442011949" target="_blank" rel="noreferrer">Springer New York, NY (1993)</a></p></li><li><p>Stephen A. Maas &quot;Nonlinear Microwave and RF Circuits&quot; 2nd edition, <a href="https://us.artechhouse.com/Nonlinear-Microwave-and-RF-Circuits-Second-Edition-P1097.aspx" target="_blank" rel="noreferrer">Artech House (1997)</a></p></li><li><p>José Carlos Pedro, David E. Root, Jianjun Xu, and Luís Cótimos Nunes. &quot;Nonlinear Circuit Simulation and Modeling: Fundamentals for Microwave Design&quot; The Cambridge RF and Microwave Engineering Series, <a href="https://www.cambridge.org/core/books/nonlinear-circuit-simulation-and-modeling/1705F3B449B4313A2BE890599DAC0E38" target="_blank" rel="noreferrer">Cambridge University Press (2018)</a></p></li><li><p>David E. Root, Jan Verspecht, Jason Horn, and Mihai Marcu. &quot;X-Parameters: Characterization, Modeling, and Design of Nonlinear RF and Microwave Components&quot; The Cambridge RF and microwave engineering series, <a href="https://www.cambridge.org/sb/academic/subjects/engineering/rf-and-microwave-engineering/x-parameters-characterization-modeling-and-design-nonlinear-rf-and-microwave-components" target="_blank" rel="noreferrer">Cambridge University Press (2013)</a></p></li><li><p>Kaidong Peng, Rick Poore, Philip Krantz, David E. Root, and Kevin P. O&#39;Brien &quot;X-parameter based design and simulation of Josephson traveling-wave parametric amplifiers for quantum computing applications&quot; <a href="http://arxiv.org/abs/2211.05328" target="_blank" rel="noreferrer">IEEE International Conference on Quantum Computing &amp; Engineering (QCE22) (2022)</a></p></li></ol><h2 id="Philosophy" tabindex="-1">Philosophy <a class="header-anchor" href="#Philosophy" aria-label="Permalink to &quot;Philosophy {#Philosophy}&quot;">​</a></h2><p>The motivation for developing this package is to simulate the gain and noise performance of ultra low noise amplifiers for quantum computing applications such as the <a href="https://www.science.org/doi/10.1126/science.aaa8525" target="_blank" rel="noreferrer">Josephson traveling-wave parametric amplifier</a>, which have thousands of linear and nonlinear circuit elements.</p><p>We prioritize speed (including compile time and time to first use), simplicity, and scalability.</p><h2 id="Related-packages-and-software" tabindex="-1">Related packages and software <a class="header-anchor" href="#Related-packages-and-software" aria-label="Permalink to &quot;Related packages and software {#Related-packages-and-software}&quot;">​</a></h2><ul><li><p><a href="https://github.com/JuliaComputing/Xyce.jl" target="_blank" rel="noreferrer">Xyce.jl</a> provides a wrapper for <a href="https://xyce.sandia.gov/" target="_blank" rel="noreferrer">Xyce</a>, the open source parallel circuit simulator from Sandia National Laboratories which can perform time domain and harmonic balance method simulations.</p></li><li><p><a href="https://github.com/JuliaComputing/Ngspice.jl" target="_blank" rel="noreferrer">NgSpice.jl</a> and <a href="https://github.com/cstook/LTspice.jl" target="_blank" rel="noreferrer">LTspice.jl</a> provide wrappers for <a href="http://ngspice.sourceforge.net/" target="_blank" rel="noreferrer">NgSpice</a> and <a href="https://www.analog.com/en/design-center/design-tools-and-calculators/ltspice-simulator.html" target="_blank" rel="noreferrer">LTspice</a>, respectively.</p></li><li><p><a href="https://github.com/SciML/ModelingToolkit.jl" target="_blank" rel="noreferrer">ModelingToolkit.jl</a> supports time domain circuit simulations from <a href="https://mtk.sciml.ai/stable/tutorials/acausal_components" target="_blank" rel="noreferrer">scratch</a> and using their <a href="https://docs.sciml.ai/ModelingToolkitStandardLibrary/stable/tutorials/rc_circuit/" target="_blank" rel="noreferrer">standard library</a></p></li><li><p><a href="https://github.com/HSU-ANT/ACME.jl" target="_blank" rel="noreferrer">ACME.jl</a> simulates electrical circuits in the time domain with an emphasis on audio effect circuits.</p></li><li><p><a href="https://cedar-eda.com" target="_blank" rel="noreferrer">Cedar EDA</a> is a Julia-based commercial cloud service for circuit simulations.</p></li><li><p><a href="https://www.keysight.com/us/en/products/software/pathwave-design-software/pathwave-advanced-design-system.html" target="_blank" rel="noreferrer">Keysight ADS</a>, <a href="https://www.cadence.com/en_US/home/tools/system-analysis/rf-microwave-design/awr-microwave-office.html" target="_blank" rel="noreferrer">Cadence AWR</a>, <a href="https://www.cadence.com/en_US/home/tools/custom-ic-analog-rf-design/circuit-simulation/spectre-rf-option.html" target="_blank" rel="noreferrer">Cadence Spectre RF</a>, and <a href="http://qucs.sourceforge.net/" target="_blank" rel="noreferrer">Qucs</a> are capable of time and frequency domain analysis of nonlinear circuits. <a href="http://wrcad.com/wrspice.html" target="_blank" rel="noreferrer">WRSPICE</a> performs time domain simulations of Josephson junction containing circuits and frequency domain simulations of linear circuits.</p></li></ul><h2 id="Funding" tabindex="-1">Funding <a class="header-anchor" href="#Funding" aria-label="Permalink to &quot;Funding {#Funding}&quot;">​</a></h2><p>We gratefully acknowledge funding from the <a href="https://aws.amazon.com/blogs/quantum-computing/announcing-the-opening-of-the-aws-center-for-quantum-computing/" target="_blank" rel="noreferrer">AWS Center for Quantum Computing</a> and the <a href="https://cqe.mit.edu/" target="_blank" rel="noreferrer">MIT Center for Quantum Engineering (CQE)</a>.</p>`,28)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
